// Edit these values once. Other nodes read them from here.
return [
  {
    json: {
      // Discord channel > Edit Channel > Integrations > Webhooks > Copy Webhook URL
      discordWebhookUrl: 'PASTE_YOUR_DISCORD_WEBHOOK_URL_HERE',
      // The M3U8 (HLS) streams to check. Add one line per stream.
      // Optional: headers: { Referer: 'https://example.com' } for streams that need them.
      // Optional: enabled: false to skip a stream without deleting it.
      streams: [
        { name: 'Mets Live', url: 'PASTE_YOUR_M3U8_URL_HERE' },
      ],
      // Seconds to wait for each request.
      timeoutSeconds: 15,
      // Failed checks in a row before posting a "down" alert. 2 skips one-off blips.
      failuresBeforeAlert: 2,
      // Reload live playlists once to make sure new video keeps arriving.
      checkLiveProgress: true,
    },
  },
];

// Checks each stream in Settings and returns Discord messages.
// Scheduled runs post only when a stream goes down or comes back.
// Manual test runs post a report for every stream.
const settings = $('Settings').first().json;
const streams = (settings.streams ?? []).filter((s) => /^https?:\/\//.test(s?.url ?? '') && s.enabled !== false);
const timeoutMs = (settings.timeoutSeconds ?? 15) * 1000;
const failuresBeforeAlert = settings.failuresBeforeAlert ?? 2;
const isManualRun = $execution.mode === 'manual';

// Resolve a playlist entry against the playlist URL. The Code node has no URL class.
function resolveUrl(ref, base) {
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(ref)) return ref;
  const origin = base.match(/^[a-z][a-z0-9+.-]*:\/\/[^/?#]+/i)[0];
  if (ref.startsWith('//')) return base.split(':')[0] + ':' + ref;
  if (ref.startsWith('/')) return origin + ref;
  const dir = base.split(/[?#]/)[0].replace(/[^/]*$/, '');
  const parts = [];
  for (const part of (dir.slice(origin.length) + ref).split('/')) {
    if (part === '..') parts.pop();
    else if (part !== '.') parts.push(part);
  }
  return origin + parts.join('/').replace(/^\/?/, '/');
}

async function get(what, url, headers, binary) {
  const res = await this.helpers.httpRequest({
    url,
    method: 'GET',
    headers,
    timeout: timeoutMs,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    encoding: binary ? 'arraybuffer' : 'text',
    json: false,
  });
  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw new Error(`${what} returned HTTP ${res.statusCode}`);
  }
  return res.body;
}

function toBytes(body) {
  if (!body) return null;
  if (body instanceof Uint8Array) return body;
  if (body instanceof ArrayBuffer) return new Uint8Array(body);
  if (Array.isArray(body.data)) return Uint8Array.from(body.data);
  return null;
}

function parsePlaylist(text, url) {
  const body = typeof text === 'string' ? text : String(text ?? '');
  if (!body.trimStart().startsWith('#EXTM3U')) {
    throw new Error('Response is not an M3U8 playlist');
  }
  const lines = body.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const variants = [];
  const segments = [];
  let mediaSequence = 0;
  let targetDuration = 6;
  let isLive = true;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.startsWith('#EXT-X-STREAM-INF')) {
      const bandwidth = Number((line.match(/BANDWIDTH=(\d+)/) ?? [])[1] ?? 0);
      const next = lines[i + 1];
      if (next && !next.startsWith('#')) variants.push({ bandwidth, url: resolveUrl(next, url) });
    } else if (line.startsWith('#EXTINF')) {
      const next = lines[i + 1];
      if (next && !next.startsWith('#')) segments.push(resolveUrl(next, url));
    } else if (line.startsWith('#EXT-X-MEDIA-SEQUENCE:')) {
      mediaSequence = Number(line.split(':')[1]);
    } else if (line.startsWith('#EXT-X-TARGETDURATION:')) {
      targetDuration = Number(line.split(':')[1]);
    } else if (line.startsWith('#EXT-X-ENDLIST')) {
      isLive = false;
    }
  }
  return { variants, segments, mediaSequence, targetDuration, isLive };
}

async function checkStream(stream) {
  const headers = stream.headers ?? {};
  let playlistUrl = stream.url;
  let playlist = parsePlaylist(await get.call(this, 'Playlist', playlistUrl, headers), playlistUrl);

  // A master playlist lists renditions. Check the highest quality one.
  let variantCount = 0;
  if (playlist.variants.length > 0) {
    variantCount = playlist.variants.length;
    playlistUrl = playlist.variants.sort((a, b) => b.bandwidth - a.bandwidth)[0].url;
    playlist = parsePlaylist(await get.call(this, 'Quality playlist', playlistUrl, headers), playlistUrl);
  }
  if (playlist.segments.length === 0) throw new Error('Playlist has no video segments');

  // Download the start of the newest segment.
  const segmentUrl = playlist.segments[playlist.segments.length - 1];
  const bytes = toBytes(await get.call(this, 'Newest video segment', segmentUrl, { ...headers, Range: 'bytes=0-4095' }, true));
  if (bytes && bytes.length === 0) throw new Error('Newest segment is empty');
  if (bytes && /^\s*<(!doctype|html|\?xml)/i.test(new TextDecoder().decode(bytes.slice(0, 64)))) {
    throw new Error('Segment URL returned a web page, not video');
  }

  // A live playlist must add new segments. Reload it after one segment length.
  if (playlist.isLive && settings.checkLiveProgress !== false) {
    const waitSeconds = Math.min(Math.max(playlist.targetDuration * 1.5, 4), 30);
    await new Promise((resolve) => setTimeout(resolve, waitSeconds * 1000));
    const again = parsePlaylist(await get.call(this, 'Playlist', playlistUrl, headers), playlistUrl);
    const moved =
      again.mediaSequence !== playlist.mediaSequence ||
      again.segments[again.segments.length - 1] !== segmentUrl;
    if (!moved) throw new Error(`Live playlist did not update in ${Math.round(waitSeconds)} seconds`);
  }

  return {
    kind: playlist.isLive ? 'live' : 'on demand',
    variantCount,
    segmentCount: playlist.segments.length,
  };
}

const results = await Promise.all(
  streams.map(async (stream) => {
    const started = Date.now();
    try {
      const info = await checkStream.call(this, stream);
      return { name: stream.name ?? stream.url, ok: true, ...info, ms: Date.now() - started };
    } catch (error) {
      return { name: stream.name ?? stream.url, ok: false, error: error.message, ms: Date.now() - started };
    }
  }),
);

function describe(r) {
  if (!r.ok) return `🔴 **${r.name}** is down: ${r.error}`;
  const renditions = r.variantCount > 1 ? `, ${r.variantCount} qualities` : '';
  return `🟢 **${r.name}** is playing (${r.kind}${renditions}, ${(r.ms / 1000).toFixed(1)}s)`;
}

if (isManualRun) {
  if (results.length === 0) return [{ json: { message: 'No streams to check. Add them in the Settings node.' } }];
  return [{ json: { message: ['📺 **Stream check**', ...results.map(describe)].join('\n'), results } }];
}

// Remember each stream's state. Static data is saved only for production runs.
const memory = $getWorkflowStaticData('global');
memory.streams = memory.streams ?? {};
const out = [];
for (const r of results) {
  const state = memory.streams[r.name] ?? { down: false, failures: 0 };
  if (r.ok) {
    if (state.down) {
      const minutes = Math.round((Date.now() - state.downSince) / 60000);
      out.push({ json: { message: `✅ **${r.name}** is back up after ${minutes} min.`, result: r } });
    }
    memory.streams[r.name] = { down: false, failures: 0 };
  } else {
    state.failures += 1;
    state.downSince = state.downSince ?? Date.now();
    if (!state.down && state.failures >= failuresBeforeAlert) {
      state.down = true;
      out.push({ json: { message: describe(r), result: r } });
    }
    memory.streams[r.name] = state;
  }
}
// Forget streams that were removed from Settings.
for (const name of Object.keys(memory.streams)) {
  if (!results.some((r) => r.name === name)) delete memory.streams[name];
}

return out;
